draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 80);
  ctx.stroke();

  // draw thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 - 50, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // draw text in thought bubble
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Truth', W/2 + 100, H/2 - 50);

  // animate thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100 + Math.sin(t) * 10, H/2 - 50 + Math.cos(t) * 10, 50, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
